 static void Check(string n,bool ok){Console.WriteLine((ok?"PASS ":"FAIL ")+n);if(ok)pass++;else fail++;}
 static Type TypeOf(string n){return typeof(Entry).Assembly.GetType("TrayLeaf."+n);}
 static MethodInfo Method(Type t,string n){return t==null?null:t.GetMethods(BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Static|BindingFlags.Instance).FirstOrDefault(m=>m.Name==n);}
 static object Call(object o,string n,params object[] a){return Method(o.GetType(),n).Invoke(o,a);}
 [STAThread] static int Main(string[] a){try{
 string work=a[0],source=a[1];Directory.CreateDirectory(work);
