 var custom=Method(typeof(Database),"CustomPrograms");var remove=Method(typeof(Database),"RemoveCustomPrograms");
 if(custom!=null&&remove!=null){db.SaveManaged(@"C:\Fixture\App.exe","测试程序","--test",true,true);db.Set(@"custom:C:\Fixture\App.exe","1");db.Set(@"args:C:\Fixture\App.exe","--test");var rows=(System.Collections.Generic.List<AppRow>)custom.Invoke(db,null);Check("custom-enumeration-preserves-launch",rows.Count==1&&rows[0].Admin&&rows[0].Args=="--test");db.Batch(rows);remove.Invoke(db,new object[]{rows});Check("custom-remove-keeps-history",((System.Collections.Generic.List<AppRow>)custom.Invoke(db,null)).Count==0&&db.Query("SELECT id FROM items").Count==1&&db.Query("SELECT path FROM managed").Count==0);}else{Check("custom-enumeration-preserves-launch",false);Check("custom-remove-keeps-history",false);}
 var relocate=Method(typeof(Database),"Relocate");
 if(relocate!=null){db.Set("migration-probe","保留 WAL 数据");string old=db.FilePath,dir=Path.Combine(work,"moved-"+Guid.NewGuid().ToString("N")),marker=Path.Combine(work,"location.txt");relocate.Invoke(db,new object[]{dir,marker});Check("sqlite-live-wal-migration",db.FilePath==Path.Combine(dir,"trayleaf.db")&&db.Get("migration-probe","")=="保留 WAL 数据"&&File.Exists(old));Check("migration-marker-persisted",File.ReadAllText(marker).Trim()==dir);Check("migration-keeps-history",db.Query("SELECT id FROM items").Count==1);var location=TypeOf("DataLocation");Check("next-start-resolves-moved-database",(string)Method(location,"Resolve").Invoke(null,new object[]{marker})==db.FilePath);db.Set("post-move","ok");using(var verify=new Database(db.FilePath))Check("migrated-connection-writable",verify.Get("post-move","")=="ok");string occupied=Path.Combine(work,"occupied-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(occupied);File.WriteAllText(Path.Combine(occupied,"trayleaf.db"),"do not overwrite");try{relocate.Invoke(db,new object[]{occupied,marker});Check("existing-destination-not-overwritten",false);}catch(TargetInvocationException){Check("existing-destination-not-overwritten",db.Get("post-move","")=="ok"&&File.ReadAllText(Path.Combine(occupied,"trayleaf.db"))=="do not overwrite");}string beforeFailure=db.FilePath,failedDir=Path.Combine(work,"failed-move-"+Guid.NewGuid().ToString("N")),badMarker=Path.Combine(work,"marker-directory-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(badMarker);try{relocate.Invoke(db,new object[]{failedDir,badMarker});Check("marker-failure-keeps-live-connection",false);Check("marker-failure-cleans-new-database",false);}catch(TargetInvocationException){Check("marker-failure-keeps-live-connection",db.FilePath==beforeFailure&&db.Get("post-move","")=="ok");Check("marker-failure-cleans-new-database",!File.Exists(Path.Combine(failedDir,"trayleaf.db")));}}else{Check("sqlite-live-wal-migration",false);Check("migration-marker-persisted",false);Check("migration-keeps-history",false);Check("next-start-resolves-moved-database",false);Check("marker-failure-keeps-live-connection",false);Check("marker-failure-cleans-new-database",false);Check("migrated-connection-writable",false);Check("existing-destination-not-overwritten",false);}
 var policy=TypeOf("UpdatePolicy");var should=Method(policy,"ShouldCheck");var mark=Method(policy,"MarkAttempt");if(should!=null&&mark!=null){var day=new DateTime(2026,11,13);Check("daily-first-launch",(bool)should.Invoke(null,new object[]{db,day}));mark.Invoke(null,new object[]{db,day});Check("no-same-day-retry",!(bool)should.Invoke(null,new object[]{db,day}));Check("next-day-check",(bool)should.Invoke(null,new object[]{db,day.AddDays(1)}));db.Set("autoCheckUpdates","0");Check("auto-update-opt-out",!(bool)should.Invoke(null,new object[]{db,day.AddDays(1)}));}else{Check("daily-first-launch",false);Check("no-same-day-retry",false);Check("next-day-check",false);Check("auto-update-opt-out",false);}
 var tint=Method(typeof(ThemeManager),"ApplyWindowTint");if(tint!=null){bool good=true;var image=(Image)w.FindName("BackgroundImage");var original=image.Source;for(int mode=0;mode<2;mode++)for(int color=0;color<6;color++){ThemeManager.Apply(w,mode.ToString(),color);tint.Invoke(null,new object[]{w,mode.ToString(),color});foreach(string fg in new[]{"Text","Muted"})foreach(string bg in new[]{"Canvas","Surface","Sidebar","Subtle"})good&=Contrast(((SolidColorBrush)w.Resources[fg]).Color,((SolidColorBrush)w.Resources[bg]).Color)>=4.5;}Check("12-palettes-readable-contrast",good);Check("window-tint-preserves-background-image",Object.ReferenceEquals(original,image.Source));}else{Check("12-palettes-readable-contrast",false);Check("window-tint-preserves-background-image",false);}
 if(policy!=null){
  ((ComboBox)w.FindName("WindowTintInput")).SelectedIndex=3;((CheckBox)w.FindName("AutoCheckUpdateInput")).IsChecked=false;Call(c,"SaveModern");Check("new-settings-persist",db.Get("windowTint","")=="3"&&db.Get("autoCheckUpdates","")=="0");
  Call(c,"PresentUpdate","v0.9.8");Check("new-version-visible",((Button)w.FindName("NewVersionBadge")).Visibility==Visibility.Visible);
  ((Button)w.FindName("NewVersionBadge")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check("badge-opens-about",((FrameworkElement)w.FindName("AboutPanel")).Visibility==Visibility.Visible);
  Call(c,"Navigate",2);Call(c,"SelectSettings",0);((Slider)w.FindName("FontScaleInput")).Value=150;w.UpdateLayout();var viewer=(ScrollViewer)w.FindName("SettingsPanel");viewer.ScrollToVerticalOffset(120);Pump(200);var bars=Find<ScrollBar>(viewer).Where(b=>b.IsVisible).ToList();Check("scroll-fades-in",bars.Count>0&&bars.Any(b=>b.Opacity>.8));Pump(1800);Console.WriteLine("SCROLL "+String.Join(",",bars.Select(b=>b.Opacity.ToString("0.00")+" capture="+b.IsMouseCaptureWithin+" visible="+b.IsVisible)));Check("scroll-fades-out",bars.Count>0&&bars.All(b=>b.Opacity<.05));
  foreach(int mode in new[]{0,1}){((ComboBox)w.FindName("ThemeInput")).SelectedIndex=mode;foreach(int percent in new[]{100,150}){((Slider)w.FindName("FontScaleInput")).Value=percent;w.UpdateLayout();Render(w,Path.Combine(work,"settings-"+mode+"-"+percent+".png"),percent==100?96:144);}}
  var customDialog=(ProgramSelectionDialog)Activator.CreateInstance(typeof(ProgramSelectionDialog),new object[]{w,new System.Collections.Generic.List<AppRow>{new AppRow{Name="自定义测试",Path=@"C:\Fixture\App.exe"}},false,true});Check("custom-dialog-removal-action",((Button)customDialog.FindName("Confirm")).Content.ToString()=="移除程序");customDialog.Close();
 }else{Check("new-settings-persist",false);Check("new-version-visible",false);Check("badge-opens-about",false);Check("scroll-fades-in",false);Check("scroll-fades-out",false);Check("custom-dialog-removal-action",false);}
 CheckNetwork();Call(c,"Exit");}app.Shutdown();Console.WriteLine("RESULT passed="+pass+" failed="+fail);return fail==0?0:1;
 }catch(Exception ex){Console.Error.WriteLine(ex);return 2;}}
 static void Pump(int ms){var frame=new System.Windows.Threading.DispatcherFrame();var timer=new System.Windows.Threading.DispatcherTimer{Interval=TimeSpan.FromMilliseconds(ms)};timer.Tick+=delegate{timer.Stop();frame.Continue=false;};timer.Start();System.Windows.Threading.Dispatcher.PushFrame(frame);}
 static System.Collections.Generic.IEnumerable<T> Find<T>(DependencyObject root)where T:DependencyObject{for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++){var child=VisualTreeHelper.GetChild(root,i);if(child is T)yield return (T)child;foreach(var next in Find<T>(child))yield return next;}}
 static void Render(Window w,string path,int dpi){var image=new System.Windows.Media.Imaging.RenderTargetBitmap((int)Math.Ceiling(w.ActualWidth*dpi/96),(int)Math.Ceiling(w.ActualHeight*dpi/96),dpi,dpi,PixelFormats.Pbgra32);image.Render(w);var encoder=new System.Windows.Media.Imaging.PngBitmapEncoder();encoder.Frames.Add(System.Windows.Media.Imaging.BitmapFrame.Create(image));using(var file=File.Create(path))encoder.Save(file);}
 static void CheckNetwork(){var method=typeof(UpdateService).GetMethods(BindingFlags.NonPublic|BindingFlags.Static).FirstOrDefault(m=>m.Name=="Latest"&&m.GetParameters().Length==3);if(method==null){Check("update-slow-header-timeout",false);Check("update-slow-body-timeout",false);Check("update-cancellation",false);Check("update-success",false);return;}for(int scenario=0;scenario<4;scenario++){int which=scenario;var listener=new System.Net.Sockets.TcpListener(System.Net.IPAddress.Loopback,0);listener.Start();int port=((System.Net.IPEndPoint)listener.LocalEndpoint).Port;var server=System.Threading.Tasks.Task.Run(async delegate{using(var client=await listener.AcceptTcpClientAsync())using(var stream=client.GetStream()){byte[] input=new byte[4096];await stream.ReadAsync(input,0,input.Length);string body="{\"tag_name\":\"v0.9.8\"}";var header=System.Text.Encoding.ASCII.GetBytes("HTTP/1.1 200 OK\r\nContent-Length: "+body.Length+"\r\nConnection: close\r\n\r\n");if(which==0||which==2)await System.Threading.Tasks.Task.Delay(1800);await stream.WriteAsync(header,0,header.Length);if(which==1)await System.Threading.Tasks.Task.Delay(1800);byte[] data=System.Text.Encoding.UTF8.GetBytes(body);await stream.WriteAsync(data,0,data.Length);}});using(var cancel=new System.Threading.CancellationTokenSource()){if(which==2)cancel.CancelAfter(100);var watch=System.Diagnostics.Stopwatch.StartNew();bool ok=false;try{var task=(System.Threading.Tasks.Task<string>)method.Invoke(null,new object[]{new Uri("http://127.0.0.1:"+port+"/"),400,cancel.Token});string value=task.GetAwaiter().GetResult();ok=which==3&&value=="v0.9.8";}catch(Exception ex){ok=which!=3&&watch.ElapsedMilliseconds<1500&&(which!=2||ex is OperationCanceledException);}Check(new[]{"update-slow-header-timeout","update-slow-body-timeout","update-cancellation","update-success"}[which],ok);Console.WriteLine("TIMING update scenario="+which+" elapsed_ms="+watch.ElapsedMilliseconds);}listener.Stop();server.ContinueWith(t=>{var observed=t.Exception;},System.Threading.Tasks.TaskContinuationOptions.OnlyOnFaulted);}}
 static double L(Color c){return .2126*Channel(c.R)+.7152*Channel(c.G)+.0722*Channel(c.B);}static double Channel(byte b){double x=b/255.0;return x<=.04045?x/12.92:Math.Pow((x+.055)/1.055,2.4);}static double Contrast(Color a,Color b){double x=L(a),y=L(b);return (Math.Max(x,y)+.05)/(Math.Min(x,y)+.05);}
